contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount, uint v) public payable {
        require(address(this).balance >= amount);
        require(amount >= 1);
        require(v >= 1 && v <= amount);
        (bool ok, ) = address(c).call{value: amount}("");
